{#
    Macro to convert a list of AC_NO values to SQL IN clause string
    Usage: {{ ac_no_list_to_sql(get_ac_no_mapping().ac_no_dp_kkh_cn) }}
    Output: '9213110364','9213111240','9213111567',...
#}

{% macro ac_no_list_to_sql(ac_no_list) %}
{%- for ac_no in ac_no_list -%}
'{{ ac_no }}'{% if not loop.last %},{% endif %}
{%- endfor -%}
{% endmacro %}

{#
    Macro to check if AC_NO is in a list (for CASE WHEN)
    Usage: {{ ac_no_in_list('AC_NO', get_ac_no_mapping().ac_no_loan_npl) }}
    Output: AC_NO IN ('9114137048','9114138403',...)
#}

{% macro ac_no_in_list(column_name, ac_no_list) %}
{{ column_name }} IN ({{ ac_no_list_to_sql(ac_no_list) }})
{% endmacro %}
